create or replace function public.get_sales_time_reports() returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$ with b as (select s.*,extract(hour from s.sale_date at time zone 'America/Sao_Paulo')::int h,extract(isodow from s.sale_date at time zone 'America/Sao_Paulo')::int w,(s.sale_date at time zone 'America/Sao_Paulo')::date d from public.sales s where s.record_type='sale_item' and not coalesce(s.cancelled,false) and s.sale_date is not null),p as (select case when h>=12 then '12:00–23:59' else '00:00–11:59' end period,count(distinct sale_number)::int orders,sum(coalesce(quantity,1))::int units,coalesce(sum(product_revenue),sum(gross_amount),0) revenue from b group by 1),hr as (select h hour,count(distinct sale_number)::int orders,sum(coalesce(quantity,1))::int units,coalesce(sum(product_revenue),sum(gross_amount),0) revenue from b group by h order by units desc limit 50),wd as (select w weekday,count(distinct sale_number)::int orders,sum(coalesce(quantity,1))::int units,coalesce(sum(product_revenue),sum(gross_amount),0) revenue,count(distinct d)::int days_observed from b group by w order by w) select jsonb_build_object('periods',coalesce((select jsonb_agg(to_jsonb(p)) from p),'[]'::jsonb),'hours',coalesce((select jsonb_agg(to_jsonb(hr)) from hr),'[]'::jsonb),'weekdays',coalesce((select jsonb_agg(to_jsonb(wd)) from wd),'[]'::jsonb)); $$; revoke all on function public.get_sales_time_reports() from public,anon; grant execute on function public.get_sales_time_reports() to authenticated;